#include <stdio.h>

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    int count[100001] = {0}; // since N <= 100000
    for (int i = 0; i < n; i++) {
        int a;
        scanf("%d", &a);
        count[a - 1]++;
    }

    // We can remove at most m-1 sports
    int removed = 0;
    while (removed < m - 1) {
        int max_idx = 0;
        for (int i = 1; i < m; i++) {
            if (count[i] > count[max_idx])
                max_idx = i;
        }
        if (count[max_idx] == 0) break; // all zero
        count[max_idx] = 0; // remove this sport
        removed++;
    }

    int ans = 0;
    for (int i = 0; i < m; i++) {
        if (count[i] > ans)
            ans = count[i];
    }

    printf("%d\n", ans);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *A = (int *)malloc(sizeof(int) * N);
    int *cnt = (int *)calloc(M + 1, sizeof(int));
    if (!A || !cnt) return 0;

    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
        cnt[A[i]]++;
    }

    int answer = N;

    for (int removed = 1; removed <= M; removed++) {
        int mx = 0;
        for (int s = 1; s <= M; s++) {
            if (cnt[s] > mx) mx = cnt[s];
        }
        if (mx < answer) answer = mx;

        int target = -1;
        for (int s = 1; s <= M; s++) {
            if (cnt[s] == mx) {
                target = s;
                break;
            }
        }

        for (int i = 0; i < N; i++) {
            if (A[i] == target) {
                cnt[A[i]]--;
                A[i] = 0;
            }
        }
    }

    printf("%d\n", answer);

    free(A);
    free(cnt);
    return 0;
}

