int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;
    vector<int> fav(N);
    vector<int> cnt(M, 0);
    for (int i = 0; i < N; i++) {
        cin >> fav[i];
        fav[i]--;
        cnt[fav[i]]++;
    }

    int ans = N; // worst case: all in one sport
    for (int k = 1; k <= M; k++) {
        // pick k sports with smallest counts
        vector<int> sorted_cnt = cnt;
        sort(sorted_cnt.begin(), sorted_cnt.end());
        vector<int> selected;
        int unselected_people = 0;
        for (int i = 0; i < M; i++) {
            if (i < M - k) {
                unselected_people += sorted_cnt[i];
            } else {
                selected.push_back(sorted_cnt[i]);
            }
        }
        // Distribute unselected people to minimize max
        // We can add them round-robin to selected sports
        int max_attendance = 0;
        for (int i = 0; i < k; i++) {
            int base = selected[i];
            int extra = unselected_people / k;
            if (i < unselected_people % k) extra++;
            max_attendance = max(max_attendance, base + extra);
        }
        ans = min(ans, max_attendance);
    }

    cout << ans << "\n";
    return 0;
}

