int main() {
    int N, M;
    cin >> N >> M;

    vector<int> cnt(M+1, 0);
    for (int i = 0; i < N; i++) {
        int x; cin >> x;
        cnt[x]++;
    }

    // counts of each sport
    vector<int> counts;
    for (int i = 1; i <= M; i++) counts.push_back(cnt[i]);
    sort(counts.begin(), counts.end());

    int lo = 1, hi = N, ans = N;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        // how many sports have count <= mid?
        int available = upper_bound(counts.begin(), counts.end(), mid) - counts.begin();
        int needed = (N + mid - 1) / mid;
        if (available >= needed) {
            ans = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }

    cout << ans << endl;
    return 0;
}

