int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> A(N, vector<int>(M));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            cin >> A[i][j];
            --A[i][j];
        }
    }

    vector<bool> removed(M, false);
    int answer = N;

    for (int iter = 0; iter < M; iter++) {
        vector<int> cnt(M, 0);

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                int sport = A[i][j];
                if (!removed[sport]) {
                    cnt[sport]++;
                    break;
                }
            }
        }

        int mx = 0, sport_mx = -1;
        for (int s = 0; s < M; s++) {
            if (!removed[s] && cnt[s] > mx) {
                mx = cnt[s];
                sport_mx = s;
            }
        }

        answer = min(answer, mx);
        removed[sport_mx] = true;
    }

    cout << answer << '\n';
    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();

        // Count participants for each sport
        int[] count = new int[M];
        for (int i = 0; i < N; i++) {
            int sport = sc.nextInt() - 1; // convert to 0-based
            count[sport]++;
        }

        // Max-heap to always get the sport with max participants
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        for (int c : count) {
            if (c > 0) pq.offer(c);
        }

        int minMax = N; // start with worst case

        // Simulate removing sports one by one
        while (!pq.isEmpty()) {
            int max = pq.poll();
            minMax = Math.min(minMax, max);
            if (pq.isEmpty()) break;
            // Remove one sport: just continue since we're removing the max one each time
        }

        System.out.println(minMax);
    }
}

