import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();

        int[][] A = new int[N][M];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                A[i][j] = fs.nextInt() - 1; // 0-index
            }
        }

        boolean[] removed = new boolean[M];
        int answer = Integer.MAX_VALUE;

        for (int step = 0; step < M; step++) {
            int[] cnt = new int[M];

            // For each participant, count their highest-ranked sport not removed
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    int sport = A[i][j];
                    if (!removed[sport]) {
                        cnt[sport]++;
                        break;
                    }
                }
            }

            int maxCount = -1;
            int maxSport = -1;
            for (int s = 0; s < M; s++) {
                if (!removed[s] && cnt[s] > maxCount) {
                    maxCount = cnt[s];
                    maxSport = s;
                }
            }

            answer = Math.min(answer, maxCount);
            removed[maxSport] = true;
        }

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
